# Enterprise Corpus: (doc_id, acl_groups, bm25_score, dense_score)
corpus = [
    ("board_mna_1", {"exec_board"}, 34.0, 0.94),
    ("board_mna_2", {"exec_board"}, 31.0, 0.92),
    ("hr_comp_plan", {"hr_confidential"}, 29.0, 0.90),
    ("eng_inc_9042", {"eng_all"}, 28.5, 0.42),         # Strong BM25 (#1), weak Dense (#5)
    ("eng_runbook", {"eng_all"}, 5.0, 0.87),           # Weak BM25 (#5), strong Dense (#1)
    ("eng_q4_spec", {"eng_all", "pm_all"}, 24.0, 0.85), # #2 in BOTH -> RRF Winner!
    ("eng_notes_1", {"eng_all"}, 18.0, 0.60),
    ("eng_notes_2", {"eng_all"}, 12.0, 0.72),
]

user_groups = {"eng_all"}

# ১) ভুল Post-Filtering (Top-3 Global Dense নিয়ে পরে ACL চেক -> Zero-Recall Starvation!)
dense_pairs = []
for doc in corpus:
    dense_pairs.append((doc[3], doc[0], doc[1]))
dense_pairs.sort(reverse=True)
top3_global = dense_pairs[:3]

post_filtered = []
for score, doc_id, acl in top3_global:
    if len(acl.intersection(user_groups)) > 0:
        post_filtered.append(doc_id)

# ২) সঠিক Pre-Retrieval ACL Filter + Hybrid RRF (k0 = 60)
allowed = []
for doc in corpus:
    if len(doc[1].intersection(user_groups)) > 0:
        allowed.append(doc)

bm25_list = []
dense_list = []
for doc in allowed:
    bm25_list.append((doc[2], doc[0]))
    dense_list.append((doc[3], doc[0]))
bm25_list.sort(reverse=True)
dense_list.sort(reverse=True)

bm25_rank = {}
for idx in range(len(bm25_list)):
    bm25_rank[bm25_list[idx][1]] = idx + 1

dense_rank = {}
for idx in range(len(dense_list)):
    dense_rank[dense_list[idx][1]] = idx + 1

k0 = 60
rrf_results = []
for doc in allowed:
    did = doc[0]
    score = (1.0 / (k0 + bm25_rank[did])) + (1.0 / (k0 + dense_rank[did]))
    rrf_results.append((score, did))
rrf_results.sort(reverse=True)

top3_rrf = []
for item in rrf_results[:3]:
    top3_rrf.append(item[1])

# ৩) ACL-Safe Semantic Cache ভেরিফায়ার (সব Cited Docs-এ লাইভ পারমিশন চেক!)
live_acl_table = {}
for doc in corpus:
    live_acl_table[doc[0]] = set(doc[1])

cached_entry = {
    "answer": "Q4 roadmap summary...",
    "cited_docs": ["eng_q4_spec", "board_mna_1"],
}

def can_serve_cache(entry, u_groups, acl_map):
    for cid in entry["cited_docs"]:
        if len(acl_map[cid].intersection(u_groups)) == 0:
            return False
    return True

exec_ok = can_serve_cache(cached_entry, {"exec_board", "eng_all"}, live_acl_table)
eng_ok = can_serve_cache(cached_entry, user_groups, live_acl_table)

# ৪) Citation Faithfulness (NLI Entailment Check, threshold = 0.80)
sentence_entail_probs = [0.94, 0.88, 0.91, 0.42]  # ৪র্থ বাক্যটি সমর্থিত নয়!
supported = 0
for p_ent in sentence_entail_probs:
    if p_ent >= 0.80:
        supported += 1
f_cite = supported / len(sentence_entail_probs)

print(f"Post-Filter Count: {len(post_filtered)} (Starved!) | Pre-Filter RRF Top-3: {top3_rrf}")
print(f"Top RRF Score ({rrf_results[0][1]}): {rrf_results[0][0]:.4f}")
print(f"Cache Serve Exec={exec_ok} | Eng={eng_ok} (Leak Blocked!) | Citation Faithfulness={f_cite:.2f}")
